const BEAT_EVERY_MS = 30_000
const FLUSH_MS = 150
const ROOTS_EVERY = 10
const MAX_REPOS = 8
const MAX_TERMS = 8
/** Lines a block keeps in memory, and in the session's state (the open or latest block, and the others). */
