// The PowerShell that stands behind each terminal tab.
//
// The engine streams a child's output but writes its standard input once and
// closes it, so keystrokes cannot be piped into a shell. Instead the shell
// listens: this script opens one runspace (so variables, functions, modules
// and the current folder last from command to command, as in a PowerShell
// window), starts a small HTTP server on 127.0.0.1 at a free port, and takes
// commands over it. What a command prints goes to this process's stdout and
// stderr, which the hooks module reads; marks on stdout (`\x1e[[wb:...]]`)
// say the server is up, that a command started, and how it ended.
//
// Every request carries the token the hooks module put in WB_TOKEN; the
// variable is cleared at once so no command (or anything it starts) sees it.
//
// A pipe is no terminal, and Node programs that see none leave out what they
// draw for one: Expo its QR code and key menu, chalk its colours. The host
// writes a small preload to the temp folder and names it in NODE_OPTIONS, so
// every Node program run here is told its output is a terminal as wide as the
// pane's screen, and FORCE_COLOR asks for colour of every program that reads it.
// Written to run under Windows PowerShell 5.1 as well as PowerShell 7.

export const HOST_SCRIPT = String.raw`
$ErrorActionPreference = 'Continue'
$utf8 = New-Object System.Text.UTF8Encoding $false
try { [Console]::OutputEncoding = $utf8 } catch {}
$OutputEncoding = $utf8
$token = $env:WB_TOKEN
$env:WB_TOKEN = $null
$isWin = [Environment]::OSVersion.Platform -eq 'Win32NT'
$crlf = [string][char]13 + [char]10
$mark = [string][char]30 + '[[wb:'
function Out-Mark([string]$m) { [Console]::Out.WriteLine($mark + $m + ']]'); [Console]::Out.Flush() }
function To-B64([string]$s) { [Convert]::ToBase64String($utf8.GetBytes($s)) }

$tty = @'
const readline = require('readline')
const columns = Number(process.env.WB_COLUMNS) || 120
for (const s of [process.stdout, process.stderr]) {
  if (s.isTTY) continue
  s.isTTY = true; s.columns = columns; s.rows = 40
  s.getColorDepth = () => 8; s.hasColors = () => true; s.getWindowSize = () => [s.columns, s.rows]
  s.cursorTo = (x, y, cb) => readline.cursorTo(s, x, y, cb)
  s.moveCursor = (dx, dy, cb) => readline.moveCursor(s, dx, dy, cb)
  s.clearLine = (d, cb) => readline.clearLine(s, d, cb)
  s.clearScreenDown = cb => readline.clearScreenDown(s, cb)
}
if (!process.stdin.isTTY) { process.stdin.isTTY = true; process.stdin.isRaw = false; process.stdin.setRawMode = m => { process.stdin.isRaw = m; return process.stdin } }
'@
try {
  $ttyFile = Join-Path ([IO.Path]::GetTempPath()) 'workbench-tty.cjs'
  [IO.File]::WriteAllText($ttyFile, $tty)
  $req = '--require "' + ($ttyFile -replace '\\', '/') + '"'
  if (-not ([string]$env:NODE_OPTIONS).Contains($req)) { $env:NODE_OPTIONS = ($req + ' ' + $env:NODE_OPTIONS).Trim() }
  $env:FORCE_COLOR = '1'
} catch {}

$rs = [runspacefactory]::CreateRunspace($Host)
$rs.Open()

function Invoke-In([string]$code, [object[]]$params) {
  $p = [powershell]::Create(); $p.Runspace = $rs
  [void]$p.AddScript($code)
  foreach ($a in $params) { [void]$p.AddArgument($a) }
  try {
    $r = $p.Invoke()
    foreach ($e in $p.Streams.Error) { Out-Mark ('info:' + (To-B64 ([string]$e))) }
    return $r
  } catch {
    Out-Mark ('info:' + (To-B64 $_.Exception.Message))
  } finally { $p.Dispose() }
}

$start = $env:WB_CWD
if (-not $start) { $start = [Environment]::CurrentDirectory }
$prof = ''
if ($env:WB_PROFILE -eq '1') { try { $prof = [string]$PROFILE.CurrentUserCurrentHost } catch {} }
[void](Invoke-In @'
$ProgressPreference = 'SilentlyContinue'
try { $PSStyle.OutputRendering = 'PlainText' } catch {}
try { Set-Location -LiteralPath $args[0] } catch {}
if ($args[1] -and (Test-Path -LiteralPath $args[1])) { . $args[1] | Out-Null }
'@ @($start, $prof))

$WRAP = @'
$global:LASTEXITCODE = 0
$global:__wbFailed = $false
# An error as PowerShell prints one for a command typed at its prompt. Where the record
# points into this wrapper (Write-Error, a throw), the line it shows would be ours, not
# the person's: those print as one line, "Name: message", as pwsh's concise view does.
function global:__wbError($e) {
  $inv = $e.InvocationInfo
  if ($inv -ne $null -and [string]$inv.Line -like '*__wbCmd*') {
    $name = ''
    if ($inv.MyCommand -ne $null) { $name = [string]$inv.MyCommand.Name }
    if (-not $name) { $name = [string]$e.CategoryInfo.Reason }
    if ($name -eq 'WriteErrorException') { $name = 'Write-Error' }
    $msg = [string]$e.Exception.Message
    if ($e.ErrorDetails -ne $null -and $e.ErrorDetails.Message) { $msg = [string]$e.ErrorDetails.Message }
    if ($name) { return $name + ': ' + $msg }
    return $msg
  }
  return (($e | Out-String -Width $__wbWidth).TrimEnd())
}
# Run as typed, so Get-History, h and r know it, as at a PowerShell prompt.
try { Add-History -InputObject ([pscustomobject]@{ CommandLine = $__wbCmd; ExecutionStatus = 'Completed'; StartExecutionTime = [datetime]::Now; EndExecutionTime = [datetime]::Now }) } catch {}
# A line that does not parse is shown as PowerShell shows it, pointing at the fault.
$__wbParse = $null
[void][System.Management.Automation.Language.Parser]::ParseInput($__wbCmd, [ref]$null, [ref]$__wbParse)
if ($__wbParse -and $__wbParse.Count -gt 0) {
  $global:__wbFailed = $true
  $f = $__wbParse[0]
  $row = [Math]::Max(1, $f.Extent.StartLineNumber)
  $src = [regex]::Split($__wbCmd, '\r?\n')
  $text = ''
  if ($row -le $src.Length) { $text = $src[$row - 1] }
  $mark = (' ' * [Math]::Max(0, $f.Extent.StartColumnNumber - 1)) + ('~' * [Math]::Max(1, [Math]::Min(80, $f.Extent.Text.Length)))
  [Console]::Error.WriteLine('ParserError: ' + [Environment]::NewLine + 'Line |' + [Environment]::NewLine + ('{0,4} |  {1}' -f $row, $text) + [Environment]::NewLine + '     |  ' + $mark + [Environment]::NewLine + '     | ' + $f.Message)
  [Console]::Error.Flush()
  return
}
try {
  . ([scriptblock]::Create($__wbCmd)) *>&1 | ForEach-Object {
    if ($_ -is [System.Management.Automation.ErrorRecord]) {
      if ([string]$_.FullyQualifiedErrorId -like 'NativeCommandError*') { [string]$_.Exception.Message }
      else {
        $global:__wbFailed = $true
        [Console]::Error.WriteLine((__wbError $_))
        [Console]::Error.Flush()
      }
    }
    elseif ($_ -is [System.Management.Automation.WarningRecord]) { 'WARNING: ' + $_.Message }
    elseif ($_ -is [System.Management.Automation.VerboseRecord]) { 'VERBOSE: ' + $_.Message }
    elseif ($_ -is [System.Management.Automation.DebugRecord]) { 'DEBUG: ' + $_.Message }
    elseif ($_ -is [System.Management.Automation.InformationRecord]) { [string]$_.MessageData }
    else { $_ }
  } | Out-String -Stream -Width $__wbWidth | ForEach-Object { [Console]::Out.WriteLine($_); [Console]::Out.Flush() }
} catch {
  $global:__wbFailed = $true
  [Console]::Error.WriteLine((__wbError $_))
  [Console]::Error.Flush()
}
'@

$script:ps = $null
$script:handle = $null
$script:cmdId = ''
$script:stopAt = $null
$script:quit = $false
$script:lastSeen = [DateTime]::UtcNow

# Every process this shell started, and theirs, found from one snapshot before any is
# ended: npx starts cmd starts node, and once the first is gone the rest no longer trace
# back here. Ended deepest first, so nothing is left running without its parent.
function Kill-Children {
  try {
    if ($isWin) {
      $all = @(Get-CimInstance Win32_Process -Property ProcessId,ParentProcessId,Name -ErrorAction Stop)
      $found = New-Object System.Collections.Generic.List[int]
      $seen = New-Object System.Collections.Generic.HashSet[int]
      [void]$seen.Add($PID)
      $queue = New-Object System.Collections.Generic.Queue[int]
      $queue.Enqueue($PID)
      while ($queue.Count -gt 0) {
        $parent = $queue.Dequeue()
        foreach ($p in $all) {
          $id = [int]$p.ProcessId
          if ([int]$p.ParentProcessId -eq $parent -and $seen.Add($id)) {
            if ($p.Name -ne 'conhost.exe') { $found.Add($id) }
            $queue.Enqueue($id)
          }
        }
      }
      for ($i = $found.Count - 1; $i -ge 0; $i--) { try { Stop-Process -Id $found[$i] -Force -ErrorAction Stop } catch {} }
    } else { & pkill -TERM -P $PID 2>&1 | Out-Null }
  } catch {}
}

function Complete-Run {
  $p = $script:ps
  $state = 'ok'
  try { [void]$p.EndInvoke($script:handle) } catch {}
  if ([string]$p.InvocationStateInfo.State -eq 'Stopped') { $state = 'stopped' }
  $exit = ''
  $cwd = ''
  try {
    $le = $rs.SessionStateProxy.GetVariable('LASTEXITCODE')
    if ($le -ne $null) { $exit = [string][int]$le }
    if ($state -eq 'ok' -and (($rs.SessionStateProxy.GetVariable('__wbFailed') -eq $true) -or ($exit -ne '' -and $exit -ne '0'))) { $state = 'fail' }
    $cwd = [string]$rs.SessionStateProxy.Path.CurrentLocation.Path
  } catch {}
  Out-Mark ('end:' + $script:cmdId + ':' + $state + ':' + $exit + ':' + (To-B64 $cwd))
  $p.Dispose()
  $script:ps = $null; $script:handle = $null; $script:cmdId = ''; $script:stopAt = $null
}

function Read-Request($ns) {
  $buf = New-Object byte[] 8192
  $ms = New-Object System.IO.MemoryStream
  $headEnd = -1
  $text = ''
  while ($headEnd -lt 0) {
    $n = $ns.Read($buf, 0, $buf.Length)
    if ($n -le 0) { return $null }
    $ms.Write($buf, 0, $n)
    $text = [Text.Encoding]::ASCII.GetString($ms.GetBuffer(), 0, [int]$ms.Length)
    $headEnd = $text.IndexOf($crlf + $crlf)
    if ($headEnd -lt 0 -and $ms.Length -gt 65536) { return $null }
  }
  $lines = $text.Substring(0, $headEnd).Split([char]10)
  $first = $lines[0].Trim().Split(' ')
  $headers = @{}
  for ($i = 1; $i -lt $lines.Length; $i++) {
    $l = $lines[$i].TrimEnd([char]13)
    $k = $l.IndexOf(':')
    if ($k -gt 0) { $headers[$l.Substring(0, $k).Trim().ToLowerInvariant()] = $l.Substring($k + 1).Trim() }
  }
  $len = 0
  if ($headers.ContainsKey('content-length')) { $len = [int]$headers['content-length'] }
  $bodyAt = $headEnd + 4
  while (($ms.Length - $bodyAt) -lt $len) {
    $n = $ns.Read($buf, 0, $buf.Length)
    if ($n -le 0) { break }
    $ms.Write($buf, 0, $n)
  }
  $body = ''
  if ($len -gt 0) { $body = $utf8.GetString($ms.GetBuffer(), $bodyAt, [Math]::Min($len, [int]$ms.Length - $bodyAt)) }
  return @{ Path = [string]$first[1]; Token = [string]$headers['x-wb-token']; Body = $body }
}

function Send-Reply($ns, [int]$code, [string]$json) {
  $b = $utf8.GetBytes($json)
  $head = "HTTP/1.1 $code OK" + $crlf + 'Content-Type: application/json; charset=utf-8' + $crlf + 'Content-Length: ' + $b.Length + $crlf + 'Connection: close' + $crlf + $crlf
  $h = [Text.Encoding]::ASCII.GetBytes($head)
  $ns.Write($h, 0, $h.Length)
  $ns.Write($b, 0, $b.Length)
  $ns.Flush()
}

function Serve($client) {
  $ns = $null
  try {
    $client.ReceiveTimeout = 3000
    $client.SendTimeout = 3000
    $ns = $client.GetStream()
    $req = Read-Request $ns
    if ($req -eq $null) { return }
    if (-not $token -or $req.Token -ne $token) { Send-Reply $ns 401 '{"error":"token"}'; return }
    $script:lastSeen = [DateTime]::UtcNow
    $body = $null
    if ($req.Body) { $body = $req.Body | ConvertFrom-Json }
    $busy = $script:handle -ne $null
    switch ($req.Path) {
      '/ping' { Send-Reply $ns 200 ('{"ok":true,"busy":' + ([string]$busy).ToLowerInvariant() + '}'); return }
      '/run' {
        if ($busy) { Send-Reply $ns 409 '{"error":"busy"}'; return }
        $id = [string]$body.id
        if ($id -notmatch '^[A-Za-z0-9_-]{1,40}$') { Send-Reply $ns 400 '{"error":"id"}'; return }
        $w = 120
        if ($body.width) { $w = [Math]::Max(40, [Math]::Min(400, [int]$body.width)) }
        $rs.SessionStateProxy.SetVariable('__wbCmd', [string]$body.cmd)
        $rs.SessionStateProxy.SetVariable('__wbWidth', $w)
        $env:WB_COLUMNS = [string]$w
        $p = [powershell]::Create(); $p.Runspace = $rs
        [void]$p.AddScript($WRAP)
        $script:ps = $p; $script:cmdId = $id; $script:stopAt = $null
        Out-Mark ('start:' + $id)
        $script:handle = $p.BeginInvoke()
        Send-Reply $ns 200 '{"ok":true}'
        return
      }
      '/stop' {
        # The programs first, while they still trace back here; then the pipeline.
        if ($busy) { Kill-Children; [void]$script:ps.BeginStop($null, $null); $script:stopAt = [DateTime]::UtcNow }
        Send-Reply $ns 200 '{"ok":true}'
        return
      }
      '/complete' {
        if ($busy) { Send-Reply $ns 200 '{"busy":true,"start":0,"length":0,"items":[]}'; return }
        $p = [powershell]::Create(); $p.Runspace = $rs
        try {
          $r = [System.Management.Automation.CommandCompletion]::CompleteInput([string]$body.text, [int]$body.cursor, $null, $p)
          $found = @($r.CompletionMatches | Select-Object -First 60 | ForEach-Object { $_.CompletionText })
          Send-Reply $ns 200 (ConvertTo-Json -Compress -Depth 3 -InputObject @{ start = $r.ReplacementIndex; length = $r.ReplacementLength; items = $found })
        } finally { $p.Dispose() }
        return
      }
      '/eval' {
        if ($busy) { Send-Reply $ns 409 '{"error":"busy"}'; return }
        $p = [powershell]::Create(); $p.Runspace = $rs
        try {
          [void]$p.AddScript([string]$body.script)
          $out = @($p.Invoke() | ForEach-Object { [string]$_ }) -join [string][char]10
          if ($out -eq '') { $out = 'null' }
          Send-Reply $ns 200 $out
        } finally { $p.Dispose() }
        return
      }
      '/exit' {
        if ($busy) { try { $script:ps.Stop() } catch {} }
        Send-Reply $ns 200 '{"ok":true}'
        $script:quit = $true
        return
      }
      default { Send-Reply $ns 404 '{"error":"route"}'; return }
    }
  } catch {
    if ($ns -ne $null) { try { Send-Reply $ns 500 (ConvertTo-Json -Compress -InputObject @{ error = $_.Exception.Message }) } catch {} }
  } finally { $client.Close() }
}

$listener = New-Object System.Net.Sockets.TcpListener ([System.Net.IPAddress]::Loopback), 0
$listener.Start()
Out-Mark ('ready:' + $listener.LocalEndpoint.Port + ':' + $PID)

while (-not $script:quit) {
  if ($script:handle -ne $null -and $script:handle.IsCompleted) { Complete-Run }
  elseif ($script:stopAt -ne $null -and ([DateTime]::UtcNow - $script:stopAt).TotalSeconds -gt 2) {
    Kill-Children
    $script:stopAt = [DateTime]::UtcNow.AddSeconds(30)
  }
  if ($listener.Pending()) { Serve $listener.AcceptTcpClient() }
  else { Start-Sleep -Milliseconds 30 }
  # Nobody has asked anything for two minutes: the session that started this is gone.
  if (([DateTime]::UtcNow - $script:lastSeen).TotalSeconds -gt 120) { $script:quit = $true }
}

try { if ($script:ps -ne $null) { $script:ps.Stop() } } catch {}
Kill-Children
try { $listener.Stop() } catch {}
[Environment]::Exit(0)
`

/** A script as `-EncodedCommand` takes it: UTF-16LE, base64. */
export function encodeCommand(script: string): string {
  let bytes = ''
  for (let at = 0; at < script.length; at += 1) {
    const code = script.charCodeAt(at)
    bytes += String.fromCharCode(code & 0xff, code >> 8)
  }

  return btoa(bytes)
}

/**
 * What pwsh is given to run: a few words that take the host script from WB_HOST, clear
 * the variable so no command sees it, and run it. The script itself rides in the
 * environment, which holds 32,767 characters of it; encoded on the command line it
 * would take nearly three times that, past what Windows lets a command line hold.
 */
export const HOST_BOOT = encodeCommand('$wbHost = $env:WB_HOST; $env:WB_HOST = $null; . ([scriptblock]::Create($wbHost))')

/**
 * For the hidden host that answers the Ports view: every process's id, parent
 * and name, and for the listening ones their command line, start time and
 * memory, as one compact JSON array of arrays.
 */
export function processScript(pids: readonly number[]): string {
  const ids = pids.filter(pid => Number.isInteger(pid) && pid > 0).join(',')

  return [
    `$ids = @(${ids})`,
    `$rows = @(Get-CimInstance Win32_Process -Property ProcessId,ParentProcessId,Name,CommandLine,CreationDate,WorkingSetSize | ForEach-Object {`,
    `  $c = ''; $t = 0; $m = 0`,
    `  if ($ids -contains [int]$_.ProcessId) {`,
    `    $c = [string]$_.CommandLine`,
    `    if ($_.CreationDate) { $t = [long]([DateTimeOffset]$_.CreationDate).ToUnixTimeMilliseconds() }`,
    `    $m = [long]$_.WorkingSetSize`,
    `  }`,
    `  ,@([int]$_.ProcessId, [int]$_.ParentProcessId, [string]$_.Name, $c, $t, $m)`,
    `})`,
    `ConvertTo-Json -InputObject $rows -Compress -Depth 3`,
  ].join('\n')
}

files.hooks/stream.ts:
// What a terminal's PowerShell host writes, read back: plain output lines,
// and the host's own marks (`\x1e[[wb:...]]`) that say it is up, that a
// command started, and how it ended. Output comes in pieces cut wherever the
// child's writes were, so a line can span two pieces: the unfinished end of
// each pipe is carried until its newline arrives.

export const MARK = '\u001e[[wb:'

export type Pipe = 'stdout' | 'stderr'

export type StreamState = { stdout: string; stderr: string }

export const FRESH: StreamState = { stdout: '', stderr: '' }

export type Ended = 'ok' | 'fail' | 'stopped'

/** A run of a line in one style, as the program's colour codes set it. */
export type Styled = { text: string; color?: string; isBold?: boolean; isDim?: boolean; isUnderline?: boolean }

export type StreamEvent =
  | { kind: 'ready'; port: number; pid: number }
  | { kind: 'start'; id: string }
  | { kind: 'end'; id: string; state: Ended; exit: number | null; cwd: string }
  | { kind: 'info'; text: string }
  | { kind: 'line'; text: string; tone: 'out' | 'err'; runs?: Styled[] }

/** Windows Terminal's "Campbell" colours for the 16 a program names: 30–37, then bright 90–97. */
export const ANSI_COLORS = [
  '#0C0C0C', '#C50F1F', '#13A10E', '#C19C00', '#0037DA', '#881798', '#3A96DD', '#CCCCCC',
  '#767676', '#E74856', '#16C60C', '#F9F1A5', '#3B78FF', '#B4009E', '#61D6D6', '#F2F2F2',
] as const

const hex = (n: number): string => Math.max(0, Math.min(255, n)).toString(16).padStart(2, '0')

/** One of the 256 colours `38;5;n` names. */
function color256(n: number): string | undefined {
  if (!Number.isInteger(n) || n < 0 || n > 255) return undefined
  if (n < 16) return ANSI_COLORS[n]
  if (n >= 232) return `#${hex(8 + (n - 232) * 10).repeat(3)}`
  const at = n - 16
  const level = (v: number): number => (v === 0 ? 0 : 55 + v * 40)

  return `#${hex(level(Math.floor(at / 36)))}${hex(level(Math.floor(at / 6) % 6))}${hex(level(at % 6))}`
}

type Style = Omit<Styled, 'text'>

/** A style after one SGR sequence's parameters (`1;33`, `38;5;214`, `0`). */
function applySgr(style: Style, params: string): Style {
  const codes = params === '' ? [0] : params.split(';').map(Number)
  let next: Style = { ...style }
  for (let at = 0; at < codes.length; at += 1) {
    const code = codes[at]!
    if (code === 0) next = {}
    else if (code === 1) next.isBold = true
    else if (code === 2) next.isDim = true
    else if (code === 22) {
      delete next.isBold
      delete next.isDim
    } else if (code === 4) next.isUnderline = true
    else if (code === 24) delete next.isUnderline
    else if (code >= 30 && code <= 37) next.color = ANSI_COLORS[code - 30]
    else if (code >= 90 && code <= 97) next.color = ANSI_COLORS[code - 90 + 8]
    else if (code === 39) delete next.color
    else if (code === 38 && codes[at + 1] === 5) {
      const picked = color256(codes[at + 2] ?? -1)
      if (picked !== undefined) next.color = picked
      at += 2
    } else if (code === 38 && codes[at + 1] === 2) {
      next.color = `#${hex(codes[at + 2] ?? 0)}${hex(codes[at + 3] ?? 0)}${hex(codes[at + 4] ?? 0)}`
      at += 4
    } else if (code === 48 && (codes[at + 1] === 5 || codes[at + 1] === 2)) at += codes[at + 1] === 5 ? 2 : 4
  }

  return next
}

const SGR = /\u001b\[([0-9;]*)m/g

/**
 * A line's styled runs as its colour codes paint it, after a carriage return keeps only
 * the last rewrite; `undefined` for a line with no colour codes, read as plain text.
 */
export function ansiRuns(raw: string): Styled[] | undefined {
  let line = raw.endsWith('\r') ? raw.slice(0, -1) : raw
  const back = line.lastIndexOf('\r')
  if (back >= 0) line = line.slice(back + 1)
  if (!line.includes('\u001b[')) return undefined
  const runs: Styled[] = []
  let style: Style = {}
  let from = 0
  const push = (piece: string): void => {
    const text = piece.replace(ANSI, '').replace(CONTROL, '')
    if (text === '') return
    const last = runs[runs.length - 1]
    const same = last !== undefined && last.color === style.color && last.isBold === style.isBold && last.isDim === style.isDim && last.isUnderline === style.isUnderline
    if (same) last.text += text
    else runs.push({ text, ...style })
  }
  for (const match of line.matchAll(SGR)) {
    push(line.slice(from, match.index))
    style = applySgr(style, match[1] ?? '')
    from = (match.index ?? 0) + match[0].length
  }
  push(line.slice(from))

  return runs.some(run => run.color !== undefined || run.isBold === true || run.isDim === true || run.isUnderline === true) ? runs : undefined
}

// CSI sequences, OSC strings (ended by BEL or ST), and lone two-byte escapes.
const ANSI = /\u001b\[[0-?]*[ -/]*[@-~]|\u001b\][^\u0007\u001b]*(?:\u0007|\u001b\\)|\u001b[@-Z\\-_]/g
// Every control character but the tab: a drawing refuses them.
const CONTROL = /[\u0000-\u0008\u000b-\u001f\u007f]/g

/**
 * One line as a terminal would leave it on screen: colour codes gone, and of
 * a line a progress bar rewrote with carriage returns, only its last state.
 */
export function clean(raw: string): string {
  let line = raw.endsWith('\r') ? raw.slice(0, -1) : raw
  const back = line.lastIndexOf('\r')
  if (back >= 0) line = line.slice(back + 1)

  return line.replace(ANSI, '').replace(CONTROL, '')
}

function decode64(text: string): string {
  try {
    const bytes = atob(text)
    const array = new Uint8Array(bytes.length)
    for (let at = 0; at < bytes.length; at += 1) array[at] = bytes.charCodeAt(at)

    return new TextDecoder().decode(array)
  } catch {
    return ''
  }
}

/** A mark's body (what follows `\x1e[[wb:`, up to `]]`), read; `undefined` for one this build does not know. */
export function readMark(body: string): StreamEvent | undefined {
  const parts = body.split(':')
  const [kind] = parts
  if (kind === 'ready') {
    const port = Number(parts[1])
    const pid = Number(parts[2])

    return Number.isInteger(port) && port > 0 ? { kind, port, pid: Number.isInteger(pid) ? pid : 0 } : undefined
  }
  if (kind === 'start' && parts[1] !== undefined && parts[1] !== '') return { kind, id: parts[1] }
  if (kind === 'end' && parts[1] !== undefined && parts[1] !== '') {
    const said = parts[2]
    const state: Ended = said === 'ok' || said === 'stopped' ? said : 'fail'
    const exit = parts[3] === undefined || parts[3] === '' ? null : Number(parts[3])

    return {
      kind,
      id: parts[1],
      state,
      exit: exit === null || Number.isFinite(exit) ? exit : null,
      cwd: decode64(parts[4] ?? ''),
    }
  }
  if (kind === 'info') return { kind, text: clean(decode64(parts[1] ?? '')) }

  return undefined
}

/** One whole line of a pipe: an output line, a mark, or output followed by a mark. */
function lineEvents(raw: string, pipe: Pipe): StreamEvent[] {
  // Windows PowerShell 5.1 speaks CLIXML on a redirected stderr: its header and records are no output.
  if (pipe === 'stderr' && /^(#< CLIXML|<Objs Version=)/.test(raw.trim())) return []
  const events: StreamEvent[] = []
  const at = pipe === 'stdout' ? raw.indexOf(MARK) : -1
  if (at < 0) {
    const runs = ansiRuns(raw)
    const line: StreamEvent = { kind: 'line', text: clean(raw), tone: pipe === 'stdout' ? 'out' : 'err' }

    return [runs === undefined ? line : { ...line, runs }]
  }
  // A command that wrote no newline at its end leaves its text before the mark.
  const before = raw.slice(0, at)
  if (clean(before) !== '') events.push({ kind: 'line', text: clean(before), tone: 'out' })
  const close = raw.indexOf(']]', at)
  const mark = close < 0 ? undefined : readMark(raw.slice(at + MARK.length, close))
  if (mark !== undefined) events.push(mark)

  return events
}

/** Takes one piece of a pipe; answers the state to carry and what the piece completed. */
export function feed(state: StreamState, pipe: Pipe, text: string): { state: StreamState; events: StreamEvent[] } {
  const held = state[pipe] + text
  const cut = held.lastIndexOf('\n')
  if (cut < 0) return { state: { ...state, [pipe]: held }, events: [] }
  const events = held
    .slice(0, cut)
    .split('\n')
    .flatMap(raw => lineEvents(raw, pipe))

  return { state: { ...state, [pipe]: held.slice(cut + 1) }, events }
}

/** What each pipe has written of its current line so far: a live progress line, shown before its newline. */
export function partial(state: StreamState): { text: string; tone: 'out' | 'err'; runs?: Styled[] }[] {
  const shown: { text: string; tone: 'out' | 'err'; runs?: Styled[] }[] = []
  const one = (raw: string, tone: 'out' | 'err'): { text: string; tone: 'out' | 'err'; runs?: Styled[] } => {
    const runs = ansiRuns(raw)

    return runs === undefined ? { text: clean(raw), tone } : { text: clean(raw), tone, runs }
  }
  if (state.stdout !== '' && !state.stdout.includes(MARK) && clean(state.stdout) !== '') shown.push(one(state.stdout, 'out'))
  if (state.stderr !== '' && clean(state.stderr) !== '') shown.push(one(state.stderr, 'err'))

  return shown
}

files.hooks/tab-name.ts:
// What a terminal tab is called after the command that keeps running in it, as
// Windows Terminal names a tab after the program in it: `npm run dev` → `dev`,
// `python app.py` → `app.py`, `docker compose up` → `compose up`.

/** The longest a tab's name gets. */
export const MAX_TAB_NAME = 18

/** Plain words that, right after a tool, name what it does rather than what it works on. */
const SUBCOMMANDS = new Set(['start', 'dev', 'run', 'serve', 'server', 'build', 'watch', 'up', 'preview', 'test', 'runserver'])

const PACKAGE_MANAGERS = new Set(['npm', 'pnpm', 'yarn', 'bun'])
/** What npm runs as a script without `run`. */
const NPM_SCRIPTS = new Set(['start', 'test', 'stop', 'restart'])
/** The package managers' own commands: anything else after pnpm, yarn or bun is a script's name. */
const PM_BUILTINS = new Set([
  'install', 'i', 'ci', 'add', 'remove', 'rm', 'uninstall', 'update', 'up', 'upgrade', 'outdated', 'audit', 'init', 'create',
  'publish', 'pack', 'link', 'unlink', 'login', 'logout', 'config', 'cache', 'list', 'ls', 'info', 'view', 'why', 'version',
  'help', 'store', 'prune', 'dedupe', 'rebuild', 'setup', 'env', 'global', 'workspace', 'workspaces',
])
/** Runners of a package's own command: npx vite, pnpm dlx, bunx. */
const RUNNERS = new Set(['npx', 'bunx', 'pnpx'])
/** Interpreters that run a file named after them. */
const INTERPRETERS = new Set(['python', 'python3', 'py', 'node', 'deno', 'ruby', 'php', 'perl', 'tsx', 'ts-node'])
/** npx options that take a value. */
const RUNNER_VALUED = new Set(['-p', '--package', '-c', '--call'])

/** A command's words, quotes kept together and removed. */
function words(text: string): string[] {
  return (text.match(/"[^"]*"?|'[^']*'?|\S+/g) ?? []).map(word => word.replace(/^["']|["']$/g, ''))
}

/** A program's name without its folder, extension or version: `C:\tools\ngrok.exe` → `ngrok`, `@scope/pkg@1` → `pkg`. */
function bare(word: string): string {
  const last = word.replace(/\\/g, '/').split('/').pop() ?? word
  const noVersion = last.replace(/(.)@.*$/, '$1')

  return noVersion.replace(/\.(exe|cmd|bat|ps1)$/i, '')
}

/** A file's name without its folder: `src/server.js` → `server.js`. */
const fileName = (word: string): string => word.replace(/\\/g, '/').split('/').pop() ?? word

const isFlag = (word: string): boolean => word.startsWith('-')

/** A word that reads as a subcommand: a plain lowercase word, no path or extension. */
const isPlainWord = (word: string | undefined): word is string => word !== undefined && /^[a-z][a-z0-9:-]*$/.test(word)

/** `tool sub` when the next word is one of the known subcommands, else the tool. */
function withSub(tool: string, next: string | undefined): string {
  return isPlainWord(next) && SUBCOMMANDS.has(next) ? `${tool} ${next}` : tool
}

/** What `npx <tool> ...` is called: the tool, and its subcommand if it has one. */
function runnerName(args: readonly string[]): string {
  let at = 0
  while (at < args.length && isFlag(args[at]!)) at += RUNNER_VALUED.has(args[at]!) ? 2 : 1
  const tool = args[at]
  if (tool === undefined) return ''

  return withSub(bare(tool), args[at + 1])
}

/** The name for one command, without the chain around it. */
function nameOne(segment: string): string {
  const all = words(segment.trim().replace(/^[&.]\s+/, ''))
  if (all.length === 0) return ''
  const program = bare(all[0]!).toLowerCase()
  const args = all.slice(1)
  const plain = args.filter(word => !isFlag(word))

  if (RUNNERS.has(program)) return runnerName(args)
  if (PACKAGE_MANAGERS.has(program)) {
    const [first, second] = plain
    if (first === undefined) return program
    if (first === 'run' || first === 'run-script') return second ?? program
    if (first === 'dlx' || first === 'exec' || first === 'x') return runnerName(args.slice(args.indexOf(first) + 1))
    if (program === 'npm') return NPM_SCRIPTS.has(first) ? first : `npm ${first}`
    if (PM_BUILTINS.has(first)) return `${program} ${first}`

    return first
  }
  if (INTERPRETERS.has(program)) {
    // `python -m http.server` runs a module: the module is the name.
    const module = args.indexOf('-m')
    if (module >= 0 && args[module + 1] !== undefined) return args[module + 1]!
    // deno task dev runs a task, as npm run does; deno run x.ts a file.
    if (program === 'deno' && plain[0] === 'task') return plain[1] ?? 'deno task'
    const rest = program === 'deno' && plain[0] === 'run' ? plain.slice(1) : plain
    const file = rest[0]
    if (file === undefined) return program
    // `python manage.py runserver`, `php artisan serve`: the script's subcommand says what runs.
    const next = rest[1]
    if (isPlainWord(next) && !next.includes('.')) return next

    return fileName(file)
  }
  if (program === 'docker' && plain[0] === 'compose') return withSub('compose', plain[1])
  if (program === 'docker-compose') return withSub('compose', plain[0])

  return withSub(program, plain[0])
}

/** `cd client`, `Set-Location ./client`, `pushd client`: the folder a chain moves into. */
function cdTarget(segment: string): string | undefined {
  const [verb, target] = words(segment.trim())
  if (verb === undefined || target === undefined) return undefined

  return /^(cd|chdir|sl|set-location|pushd|push-location)$/i.test(verb) ? target : undefined
}

export type TabName = {
  /** What the command is called, cut to fit a tab; `''` when nothing could be read from it. */
  name: string
  /** The folder the command line moved into first (`cd client; npm run dev`), as typed. */
  cdTo?: string
}

/**
 * What a tab running `cmd` is called. Of a chain (`;`, `&&`, `||`) the last command names
 * it, as the one left running; of a pipeline, its first stage, the one producing the output.
 */
export function tabName(cmd: string): TabName {
  const segments = cmd.split(/;|&&|\|\|/).map(one => one.trim()).filter(one => one !== '')
  let cdTo: string | undefined
  for (const segment of segments.slice(0, -1)) cdTo = cdTarget(segment) ?? cdTo
  const last = segments[segments.length - 1] ?? ''
  const first = last.split('|')[0] ?? last
  const name = nameOne(first)
  const cut = name.length > MAX_TAB_NAME ? `${name.slice(0, MAX_TAB_NAME - 1)}…` : name

  return cdTo === undefined ? { name: cut } : { name: cut, cdTo }
}

/** `name`, or `name 2`, `name 3`, ... so it differs from every one of `taken`. */
export function unique(name: string, taken: readonly string[]): string {
  if (!taken.includes(name)) return name
  let n = 2
  while (taken.includes(`${name} ${n}`)) n += 1

  return `${name} ${n}`
}

/**
 * A name the person gave the tab by typing it: `title frontend`, or PowerShell's own
 * `$Host.UI.RawUI.WindowTitle = "frontend"`. `''` for `title` alone, which hands naming
 * back to the commands; `undefined` when the line is not a rename.
 */
export function typedTitle(line: string): string | undefined {
  const text = line.trim()
  const titled = /^title(?:\s+(.*))?$/i.exec(text)
  if (titled !== null) return (titled[1] ?? '').trim().replace(/^["']|["']$/g, '')
  const host = /^\$host\.ui\.rawui\.windowtitle\s*=\s*(.+)$/i.exec(text)
  if (host !== null) return host[1]!.trim().replace(/^["']|["']$/g, '')

  return undefined
}

files.hooks/terminal-input.tsx:
import type { ClientModule } from 'claude-code'

import { bufferOf, edit, keepSpaces, textOf, typed } from './edit-buffer'
import type { Buffer } from './edit-buffer'

// A terminal's input line: a surface module, so each key reaches it as it is
// pressed. It keeps the line being typed and walks the history itself; what
// needs the shell (running the line, stopping a command, completing a word)
// it posts to the hooks module, which holds the PowerShell.

export type Completion = { seq: number; start: number; length: number; items: string[] }

export type InputProps = {
  termId: string
  /** What the session has printed, as coloured rows, drawn above the prompt. */
  screen: { text: string; color: string; isItalic?: boolean; isBold?: boolean; isDim?: boolean; isUnderline?: boolean }[][]
  /**
   * Rows the module fills at the least, blank ones under the prompt included: its region
   * is only as tall as what it draws, and a click there is what gives it the keys.
   */
  minRows: number
  /** The prompt's text, `PS C:\repo>`. */
  prompt: string
  isBusy: boolean
  isEnded: boolean
  /** Commands run here before, the latest last. */
  history: string[]
  /** The shell's answer to the last Tab, matched to its request by `seq`. */
  completion: Completion | null
  /** Text the pane asks to put on the line (a command to edit and run again), matched by `seq`. */
  fill: { seq: number; text: string } | null
  /** The clipboard's text, read for a paste, to go in at the cursor; matched by `seq`. */
  paste: { seq: number; text: string } | null
  /** Whether the surface sets type proportionally: spaces must then be kept by hand. */
  isProportional: boolean
  /** The prompt's colour. */
  accent: string
  /** The typed text's colour. */
  ink: string
  bad: string
  /** The colour of the quiet line under the prompt. */
  hint: string
}

type Cycle = { items: string[]; index: number; start: number; length: number; base: string }

type State = {
  buffer: Buffer
  /** Where in the history ↑ has walked to: `-1` is the line being typed. */
  back: number
  /** The line being typed, kept while ↑ shows older ones. */
  draft: string
  cycle: Cycle | null
  askedSeq: number
  fillSeq: number
  pasteSeq: number
  /** Whether the blinking cursor is in its off half. */
  isBlinkOff: boolean
  hasKeys: boolean
  note: string
  /** The whole line selected with ctrl+a: the next key acts on all of it. */
  isAllSelected?: boolean
}

const EMPTY = bufferOf('')
/** A terminal's cursor blink: half a second on, half off. */
const BLINK_MS = 530

/** The line with one completion put in for the word Tab was pressed on. */
function complete(base: string, cycle: Pick<Cycle, 'start' | 'length'>, item: string): Buffer {
  const text = base.slice(0, cycle.start) + item + base.slice(cycle.start + cycle.length)

  return { lines: [text], row: 0, col: cycle.start + item.length }
}

/** Block characters a terminal draws pictures with: a QR code, a progress bar. */
const BLOCKS = /^[ ▀▄█]+$/

/** Whether a row is a picture drawn in block characters, as Expo's QR code is. */
export function isBlockArt(row: readonly { text: string }[]): boolean {
  const text = row.map(span => span.text).join('')

  return /[▀▄█]/.test(text) && BLOCKS.test(text)
}

/**
 * What would finish `line`: the rest of the latest command in `history` (latest last) that
 * starts with it, ignoring case, as PSReadLine's history prediction; `''` for none.
 */
export function suggest(line: string, history: readonly string[]): string {
  if (line.trim() === '') return ''
  const typed = line.toLowerCase()
  for (let at = history.length - 1; at >= 0; at -= 1) {
    const one = history[at] ?? ''
    if (one.length > line.length && one.toLowerCase().startsWith(typed)) return one.slice(line.length)
  }

  return ''
}

// What each instance last set, kept here as well: keys can arrive faster than frames,
// and each must edit what the one before it left, not what was last drawn.
const latest = new WeakMap<object, State>()
// The instances whose blink is going: started once each.
const blinking = new WeakSet<object>()

const Input: ClientModule<InputProps, State> = (props, surface) => {
  const put = (next: State): void => {
    latest.set(surface, next)
    surface.setState(next)
  }
  const { Box, Text } = surface.elements
  const held = latest.get(surface) ?? surface.state
  let state: State = held ?? {
    buffer: EMPTY,
    back: -1,
    draft: '',
    cycle: null,
    askedSeq: 0,
    fillSeq: props.fill?.seq ?? 0,
    pasteSeq: props.paste?.seq ?? 0,
    isBlinkOff: false,
    hasKeys: false,
    note: '',
  }
  // A fill from the pane replaces the line once.
  if (props.fill !== null && props.fill.seq !== state.fillSeq) {
    state = { ...state, buffer: bufferOf(props.fill.text, 0, props.fill.text.length), fillSeq: props.fill.seq, back: -1, cycle: null }
    put(state)
  }
  // The clipboard's text, read for a paste, goes in at the cursor once.
  if (props.paste !== null && props.paste.seq !== state.pasteSeq) {
    const pasted = edit(state.buffer, { key: props.paste.text }, false) ?? state.buffer
    state = { ...state, buffer: props.paste.text === '' ? state.buffer : pasted, pasteSeq: props.paste.seq, back: -1, cycle: null, isBlinkOff: false }
    put(state)
  }
  // The shell answered a Tab: the first match goes in, and Tab again walks the rest.
  const answer = props.completion
  if (answer !== null && answer.seq === state.askedSeq && state.cycle === null && answer.items.length > 0) {
    const base = textOf(state.buffer)
    const cycle: Cycle = { items: answer.items, index: 0, start: answer.start, length: answer.length, base }
    state = { ...state, cycle, buffer: complete(base, cycle, answer.items[0] ?? ''), askedSeq: -1 }
    put(state)
  } else if (answer !== null && answer.seq === state.askedSeq && answer.items.length === 0) {
    state = { ...state, askedSeq: -1, note: 'no completions' }
    put(state)
  }
  if (held === undefined) put(state)

  // Keys can come faster than frames: each one edits what the last one left, not what was last drawn.
  const now = (): State => latest.get(surface) ?? state
  // Any key shows the cursor again, as a terminal does, before it goes on blinking.
  // Any key but ctrl+a lets a selection go, as it does in a PowerShell window.
  const set = (next: Partial<State>): void => put({ ...now(), hasKeys: true, note: '', isBlinkOff: false, isAllSelected: false, ...next })
  if (!blinking.has(surface)) {
    blinking.add(surface)
    surface.every(BLINK_MS, () => {
      const held = now()
      if (held.hasKeys) put({ ...held, isBlinkOff: !held.isBlinkOff })
    })
  }

  surface.onKey(raw => {
    // Arrow and other named keys as a browser names them (ArrowRight, End) are read as the engine names them.
    const named = /^Arrow(Up|Down|Left|Right)$/.exec(raw.key)?.[1]
    const key = named !== undefined ? { ...raw, key: named.toLowerCase() } : /^(End|Home|Enter|Tab|Backspace|Delete)$/.test(raw.key) ? { ...raw, key: raw.key.toLowerCase() } : raw
    const state = now()
    // Ctrl+C as a surface may hand it: the letter in either case, or the control character it types.
    const isInterrupt = (key.ctrl === true && key.key.toLowerCase() === 'c') || key.key === '\u0003' || (key.ctrl === true && key.key === 'break')
    // Ctrl+A selects the whole line, as PSReadLine does in a Windows PowerShell window.
    if ((key.ctrl === true && key.key.toLowerCase() === 'a') || key.key === '\u0001') {
      if (textOf(state.buffer) !== '') set({ isAllSelected: true, cycle: null })

      return
    }
    if (state.isAllSelected === true) {
      const whole = textOf(state.buffer)
      // With a selection, ctrl+c copies it rather than interrupting.
      if (isInterrupt) {
        surface.post({ type: 'copy', termId: props.termId, text: whole })
        set({})

        return
      }
      if (key.key === 'backspace' || key.key === 'delete') {
        set({ buffer: EMPTY, back: -1, cycle: null })

        return
      }
      const text = typed(key)
      if (text !== undefined) {
        set({ buffer: bufferOf(text, 0, text.length), back: -1, cycle: null })

        return
      }
      if (key.key === 'left' || key.key === 'home') {
        set({ buffer: bufferOf(whole, 0, 0) })

        return
      }
      if (key.key === 'right' || key.key === 'end') {
        set({ buffer: bufferOf(whole, 0, whole.length) })

        return
      }
      // A paste replaces the selection: the line empties now, and the clipboard's text goes in when it comes.
      const isPasteKey = ((key.ctrl === true || key.meta === true) && key.key.toLowerCase() === 'v') || (key.shift === true && key.key === 'insert')
      if (isPasteKey) put({ ...state, buffer: EMPTY, isAllSelected: false })
    }
    if (isInterrupt) {
      if (props.isBusy) surface.post({ type: 'stop', termId: props.termId })
      set({ buffer: EMPTY, back: -1, cycle: null })

      return
    }
    // Paste: the clipboard is the hooks module's to read; it answers with the text in `paste`.
    const isPaste = ((key.ctrl === true || key.meta === true) && key.key.toLowerCase() === 'v') || (key.shift === true && key.key === 'insert')
    if (isPaste) {
      surface.post({ type: 'paste', termId: props.termId, seq: Date.now() % 1_000_000_000 })
      set({})

      return
    }
    if ((key.ctrl === true && key.key.toLowerCase() === 'l') || key.key === '\u000c') {
      surface.post({ type: 'clear', termId: props.termId })
      set({})

      return
    }
    if (key.key === 'return' || key.key === 'enter') {
      const line = textOf(state.buffer)
      if (props.isEnded) {
        surface.post({ type: 'restart', termId: props.termId })
        set({})

        return
      }
      if (props.isBusy) {
        set({ note: 'still running: ctrl+c stops it' })

        return
      }
      surface.post({ type: 'run', termId: props.termId, text: line })
      set({ buffer: EMPTY, back: -1, draft: '', cycle: null })

      return
    }
    if (key.key === 'tab') {
      const cycle = state.cycle
      if (cycle !== null && cycle.items.length > 1) {
        const step = key.shift === true ? -1 : 1
        const index = (cycle.index + step + cycle.items.length) % cycle.items.length
        set({ cycle: { ...cycle, index }, buffer: complete(cycle.base, cycle, cycle.items[index] ?? '') })

        return
      }
      if (props.isBusy || cycle !== null) return
      const seq = Date.now() % 1_000_000_000
      surface.post({ type: 'complete', termId: props.termId, text: textOf(state.buffer), cursor: state.buffer.col, seq })
      set({ askedSeq: seq })

      return
    }
    if (key.key === 'up' || key.key === 'down') {
      const list = props.history
      if (list.length === 0) return
      const back = key.key === 'up' ? Math.min(list.length - 1, state.back + 1) : state.back - 1
      if (back < 0) {
        set({ back: -1, buffer: bufferOf(state.draft, 0, state.draft.length), cycle: null })

        return
      }
      const shown = list[list.length - 1 - back] ?? ''
      set({
        back,
        draft: state.back === -1 ? textOf(state.buffer) : state.draft,
        buffer: bufferOf(shown, 0, shown.length),
        cycle: null,
      })

      return
    }
    // A suggestion is taken as PSReadLine takes one: → or End at the end of the line takes
    // it all, ctrl+→ the next word of it.
    const typedLine = textOf(state.buffer)
    const offered = state.buffer.col === typedLine.length && state.back === -1 && state.cycle === null ? suggest(typedLine, props.history) : ''
    if (offered !== '' && key.ctrl !== true && (key.key === 'right' || key.key === 'end')) {
      set({ buffer: bufferOf(typedLine + offered, 0, typedLine.length + offered.length) })

      return
    }
    if (offered !== '' && key.ctrl === true && key.key === 'right') {
      const word = /^\s*\S+/.exec(offered)?.[0] ?? offered
      set({ buffer: bufferOf(typedLine + word, 0, typedLine.length + word.length) })

      return
    }
    const next = edit(state.buffer, key, false)
    if (next !== undefined) set({ buffer: next, cycle: null, back: -1 })
  })

  const line = state.buffer.lines[0] ?? ''
  const col = state.buffer.col
  // On a cell grid a line wider than its room scrolls with the cursor; set in proportional
  // type, where a cell count says little, it wraps under the prompt as a terminal's does.
  const room = props.isProportional ? Infinity : Math.max(10, (surface.columns > 0 ? surface.columns : 60) - props.prompt.length - 2)
  const left = col >= room ? col - room + 1 : 0
  const show = (text: string): string => (props.isProportional ? keepSpaces(text) : text)
  const before = show(line.slice(left, col))
  const under = line[col] ?? ' '
  const after = show(line.slice(col + 1, left + room))
  const cycle = state.cycle
  // The rest of the latest command run here that starts as this line does, in grey after
  // the cursor, as PowerShell 7's prediction shows it; the cursor sits on its first letter.
  const ghost =
    col === line.length && state.back === -1 && cycle === null && state.isAllSelected !== true && !props.isBusy && !props.isEnded ? suggest(line, props.history) : ''
  const ghostShown = ghost.slice(0, Math.max(0, left + room - col))
  const hint = props.isEnded
    ? 'session ended: Enter restarts it'
    : state.note !== ''
      ? state.note
      : props.isBusy
        ? 'ctrl+c stops'
        : ''

  // The region is the whole screen, so a click anywhere on it takes the keys: what the
  // session printed, the prompt after it as PowerShell prints it (and after that, quietly,
  // the completions to pick from or a note), then the empty black below.
  return (
    <Box flexDirection="column" width="100%" flexGrow={1}>
      {props.screen.map(row =>
        // Set in proportional type, block characters would not line up and a QR code would not
        // scan: each is drawn as one cell instead, its top and bottom halves filled as the glyph is.
        props.isProportional && isBlockArt(row) ? (
          <Box flexDirection="row">
            {row.flatMap(span =>
              [...span.text].map(glyph => (
                <Box flexDirection="column" width={1} height={1} flexShrink={0}>
                  <Box height={0.5} {...(glyph === '▀' || glyph === '█' ? { backgroundColor: span.color } : {})} />
                  <Box height={0.5} {...(glyph === '▄' || glyph === '█' ? { backgroundColor: span.color } : {})} />
                </Box>
              )),
            )}
          </Box>
        ) : (
          <Box flexDirection="row">
            {row.length === 0 ? (
              <Text> </Text>
            ) : (
              row.map(span => (
                <Text color={span.color} italic={span.isItalic === true} bold={span.isBold === true} dimColor={span.isDim === true} underline={span.isUnderline === true}>
                  {show(span.text)}
                </Text>
              ))
            )}
          </Box>
        ),
      )}
      <Box flexDirection="row" flexWrap="wrap">
        <Text color={props.isEnded ? props.bad : props.accent}>{show(props.prompt)}</Text>
        {/* Selected with ctrl+a: the whole line highlighted, as a selection in a PowerShell window. */}
        {state.isAllSelected === true && (
          <Text inverse color={props.ink}>
            {show(line.slice(left, left + room))}
          </Text>
        )}
        {state.isAllSelected !== true && <Text color={props.ink}>{before}</Text>}
        {/* Each piece a child of this row itself, so the suggestion stays on the prompt's line. */}
        {ghostShown !== '' && (
          <Text inverse={!state.isBlinkOff} color={props.hint}>
            {show(ghostShown.slice(0, 1))}
          </Text>
        )}
        {ghostShown !== '' && ghostShown.length > 1 && <Text color={props.hint}>{show(ghostShown.slice(1))}</Text>}
        {ghostShown === '' && state.isAllSelected !== true && (
          <Text inverse={!props.isBusy && !state.isBlinkOff} color={props.ink}>
            {show(under)}
          </Text>
        )}
        {ghostShown === '' && state.isAllSelected !== true && after !== '' && <Text color={props.ink}>{after}</Text>}
        {cycle !== null && cycle.items.length > 1 ? (
          <Box flexDirection="row" columnGap={2} marginLeft={2}>
            {cycle.items.slice(0, 12).map((item, at) => (
              <Text key={`c${at}`} inverse={at === cycle.index} color={props.hint}>
                {show(item)}
              </Text>
            ))}
            {cycle.items.length > 12 && <Text color={props.hint}>+{cycle.items.length - 12}</Text>}
          </Box>
        ) : (
          hint !== '' && (
            <Box marginLeft={2}>
              <Text color={props.hint}>{hint}</Text>
            </Box>
          )
        )}
      </Box>
      {Array.from({ length: Math.max(2, props.minRows - props.screen.length - 1) }, (_, at) => (
        <Text key={`pad${at}`}> </Text>
      ))}
    </Box>
  )
}

export default Input

